// orderAsset is how Assets come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderAsset = []sqlpage.Order{
	{Column: entAsset.FieldDateCreated, Desc: false},
	{Column: entAsset.FieldId, Desc: false},
}

func afterAsset(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextAsset(last *ent.Asset, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByAsset is an order as ent orders a query by it.
func orderByAsset(by []sqlpage.Order) []entAsset.OrderOption {
	out := make([]entAsset.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// AssetPageSize is what a request that did not say gets, and
	// AssetPageLimit is the most it gets however loudly it asks.
	AssetPageSize  = 50
	AssetPageLimit = 500

	// AssetFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	AssetFilterLimit = 8
)

// List answers with the Assets that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkAsset) List(ctx context.Context, req *rove.AssetListRequest) (*rove.AssetListResponse, error) {
	q := s.store.Db.Asset.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.AssetNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > AssetFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), AssetFilterLimit)
		}

		ps := make([]predicate.Asset, 0, len(fs))
		for i, f := range fs {
			p, err := filterAsset(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entAsset.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderAsset, afterAsset, nextAsset, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), AssetPageSize, AssetPageLimit)
	us, err := q.Order(orderByAsset(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.Asset, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.AssetListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterAsset turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterAsset(f *rove.AssetFilter) (predicate.Asset, error) {
	ps := make([]predicate.Asset, 0, 1)
	if f.HasRef() {
		p, err := bare.AssetPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasKind() {
		ps = append(ps, entAsset.KindEQ(f.GetKind()))
	}
	if f.HasStatus() {
		ps = append(ps, entAsset.StatusEQ(f.GetStatus()))
	}
	if f.HasType() {
		w := f.GetType()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "type: %s", err)
			}

			ps = append(ps, entAsset.TypeIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetTypePick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entAsset.HasTypeWith(q))
		}
	}
	if f.HasModel() {
		w := f.GetModel()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "model: %s", err)
			}

			ps = append(ps, entAsset.ModelIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.ItemModelPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entAsset.HasModelWith(q))
		}
	}
	if f.HasParentId() {
		k, err := entuuid.FromBytes(f.GetParentId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "parent_id: %s", err)
		}

		ps = append(ps, entAsset.ParentIdEQ(k))
	}
	if f.HasCustodian() {
		w := f.GetCustodian()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "custodian: %s", err)
			}

			ps = append(ps, entAsset.CustodianIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.PartyPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entAsset.HasCustodianWith(q))
		}
	}
	if f.HasTag() {
		ps = append(ps, entAsset.TagEQ(f.GetTag()))
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Asset(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(entAsset.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(entAsset.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if m := f.GetAttributes(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Asset(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(entAsset.FieldAttributes, sqljson.Path(k)),
					sqljson.ValueEQ(entAsset.FieldAttributes, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entAsset.And(ps...), nil
}

// AssetService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Asset. A service is named for the entity it
// is about, so the name carries it.
var AssetService = watch.ServiceOf(rove.AssetService_Get_FullMethodName)

// Watch answers with the Assets this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkAsset) Watch(req *rove.AssetWatchRequest, out grpc.ServerStreamingServer[rove.AssetWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > AssetFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), AssetFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchAssetKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, AssetService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*rove.AssetWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, rove.AssetWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(rove.AssetWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkAsset) watchNow(
	ctx context.Context, req *rove.AssetWatchRequest, out grpc.ServerStreamingServer[rove.AssetWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, rove.AssetListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*rove.AssetWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, rove.AssetWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(rove.AssetWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkAsset) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*rove.Asset, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, rove.AssetGetRequest_builder{
		Ref: rove.AssetRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchAssetKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkAsset) watchAssetKeys(
	ctx context.Context, fs []*rove.AssetFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, rove.AssetGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

