const (
	// AttachmentPageSize is what a request that did not say gets, and
	// AttachmentPageLimit is the most it gets however loudly it asks.
	AttachmentPageSize  = 50
	AttachmentPageLimit = 200

	// AttachmentFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	AttachmentFilterLimit = 32
)

// List answers with the Attachments that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkAttachment) List(ctx context.Context, req *rove.AttachmentListRequest) (*rove.AttachmentListResponse, error) {
	q := s.store.Db.Attachment.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.AttachmentNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > AttachmentFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), AttachmentFilterLimit)
		}

		ps := make([]predicate.Attachment, 0, len(fs))
		for i, f := range fs {
			p, err := filterAttachment(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entAttachment.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderAttachment, afterAttachment, nextAttachment, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), AttachmentPageSize, AttachmentPageLimit)
	us, err := q.Order(orderByAttachment(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.Attachment, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.AttachmentListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterAttachment turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterAttachment(f *rove.AttachmentFilter) (predicate.Attachment, error) {
	ps := make([]predicate.Attachment, 0, 1)
	if f.HasRef() {
		p, err := bare.AttachmentPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasSubjectId() {
		k, err := entuuid.FromBytes(f.GetSubjectId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "subject_id: %s", err)
		}

		ps = append(ps, entAttachment.SubjectIdEQ(k))
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entAttachment.And(ps...), nil
}

