// tenantAtCountTenant is the tenant "count.tenant" arrives at.
func (s sinkCountFinding) tenantAtCountTenant(ctx context.Context, ref *rove.InventoryCountRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("count", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "InventoryCount", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.InventoryCountPick(ref)
		if err != nil {
			return nil, pderr.At("count", err)
		}

		k, err := s.store.Db.InventoryCount.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("count", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtAssetTenant is the tenant "asset.tenant" arrives at.
