// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkParty) Apply(ctx context.Context, req *rove.PartyApplyRequest) (*rove.Party, error) {
	seen.Forget(s.store.Db.Driver(), "Party", req.GetRef())

	return s.PartyServiceServer.Apply(ctx, req)
}

// Patch forgets what the transaction was told about the row, before it is
// written; see [sinkParty.Apply].
func (s sinkParty) Patch(ctx context.Context, req *rove.PartyPatchRequest) (*rove.Party, error) {
	seen.Forget(s.store.Db.Driver(), "Party", req.GetRef())

	return s.PartyServiceServer.Patch(ctx, req)
}

// orderParty is how Partys come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderParty = []sqlpage.Order{
	{Column: entParty.FieldDateCreated, Desc: false},
	{Column: entParty.FieldId, Desc: false},
}

func afterParty(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextParty(last *ent.Party, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByParty is an order as ent orders a query by it.
func orderByParty(by []sqlpage.Order) []entParty.OrderOption {
	out := make([]entParty.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// PartyPageSize is what a request that did not say gets, and
	// PartyPageLimit is the most it gets however loudly it asks.
	PartyPageSize  = 50
	PartyPageLimit = 500

	// PartyFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	PartyFilterLimit = 32
)

// List answers with the Partys that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkParty) List(ctx context.Context, req *rove.PartyListRequest) (*rove.PartyListResponse, error) {
	q := s.store.Db.Party.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.PartyNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > PartyFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), PartyFilterLimit)
		}

		ps := make([]predicate.Party, 0, len(fs))
		for i, f := range fs {
			p, err := filterParty(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entParty.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderParty, afterParty, nextParty, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), PartyPageSize, PartyPageLimit)
	us, err := q.Order(orderByParty(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.Party, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.PartyListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterParty turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterParty(f *rove.PartyFilter) (predicate.Party, error) {
	ps := make([]predicate.Party, 0, 1)
	if f.HasRef() {
		p, err := bare.PartyPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasKind() {
		ps = append(ps, entParty.KindEQ(f.GetKind()))
	}
	if f.HasParentId() {
		k, err := entuuid.FromBytes(f.GetParentId())
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "parent_id: %s", err)
		}

		ps = append(ps, entParty.ParentIdEQ(k))
	}
	if f.HasHolder() {
		w := f.GetHolder()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "holder: %s", err)
			}

			ps = append(ps, entParty.HolderIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.HolderPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entParty.HasHolderWith(q))
		}
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Party(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(entParty.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(entParty.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entParty.And(ps...), nil
}

// PartyService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Party. A service is named for the entity it
// is about, so the name carries it.
var PartyService = watch.ServiceOf(rove.PartyService_Get_FullMethodName)

// Watch answers with the Partys this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkParty) Watch(req *rove.PartyWatchRequest, out grpc.ServerStreamingServer[rove.PartyWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > PartyFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), PartyFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchPartyKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, PartyService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*rove.PartyWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, rove.PartyWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(rove.PartyWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkParty) watchNow(
	ctx context.Context, req *rove.PartyWatchRequest, out grpc.ServerStreamingServer[rove.PartyWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, rove.PartyListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*rove.PartyWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, rove.PartyWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(rove.PartyWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkParty) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*rove.Party, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, rove.PartyGetRequest_builder{
		Ref: rove.PartyRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchPartyKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkParty) watchPartyKeys(
	ctx context.Context, fs []*rove.PartyFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, rove.PartyGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

type sinkPlacement struct {
	rove.PlacementServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Placement() rove.PlacementServiceServer {
	v := sinkPlacement{s.Server.Placement(), s.Server.Store, s.w, s.namer, s.joined}
	v.PlacementServiceServer = bare.PlacementWithAddRule(v.PlacementServiceServer, v.admit)
	return v
}

// admit is what is said of the tenancy of a row an Add of Placement writes:
// it refuses it when its paths to a tenant do not agree.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.Placement].
func (s sinkPlacement) admit(ctx context.Context, req *rove.PlacementAddRequest) (*rove.PlacementAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return r, nil
}

// Erase forgets what the transaction was told about the row, before it is
// erased: whether a frame may see it, and where a walk from it arrives.
// Neither is true of a row that is gone, nor of another put under its
// key. See [seen.Forget].
func (s sinkPlacement) Erase(ctx context.Context, req *rove.PlacementRef) (*rove.PlacementEraseResponse, error) {
	seen.Forget(s.store.Db.Driver(), "Placement", req)

	return s.PlacementServiceServer.Erase(ctx, req)
}

// Apply forgets what the transaction was told about the row, before it is
// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkPlacement) Apply(ctx context.Context, req *rove.PlacementApplyRequest) (*rove.Placement, error) {
	seen.Forget(s.store.Db.Driver(), "Placement", req.GetRef())

	return s.PlacementServiceServer.Apply(ctx, req)
}

// Patch forgets what the transaction was told about the row, before it is
// written; see [sinkPlacement.Apply].
func (s sinkPlacement) Patch(ctx context.Context, req *rove.PlacementPatchRequest) (*rove.Placement, error) {
	seen.Forget(s.store.Db.Driver(), "Placement", req.GetRef())

	return s.PlacementServiceServer.Patch(ctx, req)
}

// tenantAtTenant is the tenant "tenant" arrives at.
func (s sinkPlacement) tenantAtTenant(ctx context.Context, ref *rove.TenantRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("tenant", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Tenant", "", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.TenantPick(ref)
		if err != nil {
			return nil, pderr.At("tenant", err)
		}

		k, err := s.store.Db.Tenant.Query().Where(pick).OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("tenant", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtChildTenant is the tenant "child.tenant" arrives at.
func (s sinkPlacement) tenantAtChildTenant(ctx context.Context, ref *rove.AssetRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("child", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Asset", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.AssetPick(ref)
		if err != nil {
			return nil, pderr.At("child", err)
		}

		k, err := s.store.Db.Asset.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("child", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtParentTenant is the tenant "parent.tenant" arrives at.
func (s sinkPlacement) tenantAtParentTenant(ctx context.Context, ref *rove.AssetRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("parent", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Asset", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.AssetPick(ref)
		if err != nil {
			return nil, pderr.At("parent", err)
		}

		k, err := s.store.Db.Asset.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("parent", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkPlacement) tenancy(ctx context.Context, req *rove.PlacementAddRequest) error {
	want, err := s.tenantAtTenant(ctx, req.GetTenant())
	if err != nil {
		return err
	}

	if req.HasChild() {
		got, err := s.tenantAtChildTenant(ctx, req.GetChild())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("child",
				"it is in another tenant than tenant")
		}
	}

	if req.HasParent() {
		got, err := s.tenantAtParentTenant(ctx, req.GetParent())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("parent",
				"it is in another tenant than tenant")
		}
	}

	return nil
}

// orderPlacement is how Placements come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderPlacement = []sqlpage.Order{
	{Column: entPlacement.FieldDateCreated, Desc: false},
	{Column: entPlacement.FieldId, Desc: false},
}

func afterPlacement(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextPlacement(last *ent.Placement, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByPlacement is an order as ent orders a query by it.
func orderByPlacement(by []sqlpage.Order) []entPlacement.OrderOption {
	out := make([]entPlacement.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// PlacementPageSize is what a request that did not say gets, and
	// PlacementPageLimit is the most it gets however loudly it asks.
	PlacementPageSize  = 100
	PlacementPageLimit = 1000

	// PlacementFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	PlacementFilterLimit = 32
)

// List answers with the Placements that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkPlacement) List(ctx context.Context, req *rove.PlacementListRequest) (*rove.PlacementListResponse, error) {
	q := s.store.Db.Placement.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.PlacementNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > PlacementFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), PlacementFilterLimit)
		}

		ps := make([]predicate.Placement, 0, len(fs))
		for i, f := range fs {
			p, err := filterPlacement(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entPlacement.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderPlacement, afterPlacement, nextPlacement, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), PlacementPageSize, PlacementPageLimit)
	us, err := q.Order(orderByPlacement(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.Placement, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.PlacementListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterPlacement turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterPlacement(f *rove.PlacementFilter) (predicate.Placement, error) {
	ps := make([]predicate.Placement, 0, 1)
	if f.HasRef() {
		p, err := bare.PlacementPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasChild() {
		w := f.GetChild()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "child: %s", err)
			}

			ps = append(ps, entPlacement.ChildIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entPlacement.HasChildWith(q))
		}
	}
	if f.HasParent() {
		w := f.GetParent()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "parent: %s", err)
			}

			ps = append(ps, entPlacement.ParentIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entPlacement.HasParentWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entPlacement.And(ps...), nil
}

