// orderByTenantContract is an order as ent orders a query by it.
func orderByTenantContract(by []sqlpage.Order) []entTenantContract.OrderOption {
	out := make([]entTenantContract.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// TenantContractPageSize is what a request that did not say gets, and
	// TenantContractPageLimit is the most it gets however loudly it asks.
	TenantContractPageSize  = 20
	TenantContractPageLimit = 100

	// TenantContractFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	TenantContractFilterLimit = 32
)

// List answers with the TenantContracts that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkTenantContract) List(ctx context.Context, req *rove.TenantContractListRequest) (*rove.TenantContractListResponse, error) {
	q := s.store.Db.TenantContract.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.TenantContractNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > TenantContractFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), TenantContractFilterLimit)
		}

		ps := make([]predicate.TenantContract, 0, len(fs))
		for i, f := range fs {
			p, err := filterTenantContract(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entTenantContract.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderTenantContract, afterTenantContract, nextTenantContract, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), TenantContractPageSize, TenantContractPageLimit)
	us, err := q.Order(orderByTenantContract(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.TenantContract, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.TenantContractListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterTenantContract turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterTenantContract(f *rove.TenantContractFilter) (predicate.TenantContract, error) {
	ps := make([]predicate.TenantContract, 0, 1)
	if f.HasRef() {
		p, err := bare.TenantContractPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entTenantContract.And(ps...), nil
}

