// left is the row a write left of the thing `key` names: `image`, the one
// it handed over, or the row there is now when it handed none -- an
// Erase's, read as a check of the rows reads it, erased softly or not --
// and nil for a write that left none: an erase that took the row with it.
func left(ctx context.Context, s bare.Server, key pdid.Id, image proto.Message) (proto.Message, error) {
	if image != nil && image.ProtoReflect().IsValid() {
		return image, nil
	}

	var vs []audit.Live
	var err error
	switch key.Domain() {
	case AccessReviewDomain:
		vs, err = rowsAccessReview(ctx, s.Db, entAccessReview.IdEQ(uuid.UUID(key)))
	case AliasHoldDomain:
		vs, err = rowsAliasHold(ctx, s.Db, entAliasHold.IdEQ(uuid.UUID(key)))
	case AllocationDomain:
		vs, err = rowsAllocation(ctx, s.Db, entAllocation.IdEQ(uuid.UUID(key)))
	case AssetDomain:
		vs, err = rowsAsset(ctx, s.Db, entAsset.IdEQ(uuid.UUID(key)))
	case AssetTypeDomain:
		vs, err = rowsAssetType(ctx, s.Db, entAssetType.IdEQ(uuid.UUID(key)))
	case AttachmentDomain:
		vs, err = rowsAttachment(ctx, s.Db, entAttachment.IdEQ(uuid.UUID(key)))
	case BookableDomain:
		vs, err = rowsBookable(ctx, s.Db, entBookable.IdEQ(uuid.UUID(key)))
	case CliLoginDomain:
		vs, err = rowsCliLogin(ctx, s.Db, entCliLogin.IdEQ(uuid.UUID(key)))
	case CountFindingDomain:
		vs, err = rowsCountFinding(ctx, s.Db, entCountFinding.IdEQ(uuid.UUID(key)))
	case CustodyDomain:
		vs, err = rowsCustody(ctx, s.Db, entCustody.IdEQ(uuid.UUID(key)))
	case CustodyLineDomain:
		vs, err = rowsCustodyLine(ctx, s.Db, entCustodyLine.IdEQ(uuid.UUID(key)))
	case EventDomain:
		vs, err = rowsEvent(ctx, s.Db, entEvent.IdEQ(uuid.UUID(key)))
	case FactDomain:
		vs, err = rowsFact(ctx, s.Db, entFact.IdEQ(uuid.UUID(key)))
	case HandoffDomain:
		vs, err = rowsHandoff(ctx, s.Db, entHandoff.IdEQ(uuid.UUID(key)))
	case HolderDomain:
		vs, err = rowsHolder(ctx, s.Db, entHolder.IdEQ(uuid.UUID(key)))
	case InventoryCountDomain:
		vs, err = rowsInventoryCount(ctx, s.Db, entInventoryCount.IdEQ(uuid.UUID(key)))
	case InvitationDomain:
		vs, err = rowsInvitation(ctx, s.Db, entInvitation.IdEQ(uuid.UUID(key)))
	case ItemModelDomain:
		vs, err = rowsItemModel(ctx, s.Db, entItemModel.IdEQ(uuid.UUID(key)))
	case LabelDomain:
		vs, err = rowsLabel(ctx, s.Db, entLabel.IdEQ(uuid.UUID(key)))
	case LegalHoldDomain:
		vs, err = rowsLegalHold(ctx, s.Db, entLegalHold.IdEQ(uuid.UUID(key)))
	case LinkDomain:
		vs, err = rowsLink(ctx, s.Db, entLink.IdEQ(uuid.UUID(key)))
	case NotificationDomain:
		vs, err = rowsNotification(ctx, s.Db, entNotification.IdEQ(uuid.UUID(key)))
	case PartyDomain:
		vs, err = rowsParty(ctx, s.Db, entParty.IdEQ(uuid.UUID(key)))
	case PlacementDomain:
		vs, err = rowsPlacement(ctx, s.Db, entPlacement.IdEQ(uuid.UUID(key)))
	case PurchaseDomain:
		vs, err = rowsPurchase(ctx, s.Db, entPurchase.IdEQ(uuid.UUID(key)))
	case PurchaseLineDomain:
		vs, err = rowsPurchaseLine(ctx, s.Db, entPurchaseLine.IdEQ(uuid.UUID(key)))
	case ReservationDomain:
		vs, err = rowsReservation(ctx, s.Db, entReservation.IdEQ(uuid.UUID(key)))
	case ReservationItemDomain:
		vs, err = rowsReservationItem(ctx, s.Db, entReservationItem.IdEQ(uuid.UUID(key)))
	case SearchStaleDomain:
		vs, err = rowsSearchStale(ctx, s.Db, entSearchStale.IdEQ(uuid.UUID(key)))
	case SessionDomain:
		vs, err = rowsSession(ctx, s.Db, entSession.IdEQ(uuid.UUID(key)))
	case SignInFailureDomain:
		vs, err = rowsSignInFailure(ctx, s.Db, entSignInFailure.IdEQ(uuid.UUID(key)))
	case StewardshipDomain:
		vs, err = rowsStewardship(ctx, s.Db, entStewardship.IdEQ(uuid.UUID(key)))
	case StockDomain:
		vs, err = rowsStock(ctx, s.Db, entStock.IdEQ(uuid.UUID(key)))
	case StockMovementDomain:
		vs, err = rowsStockMovement(ctx, s.Db, entStockMovement.IdEQ(uuid.UUID(key)))
	case TenantDomain:
		vs, err = rowsTenant(ctx, s.Db, entTenant.IdEQ(uuid.UUID(key)))
	case TenantContractDomain:
		vs, err = rowsTenantContract(ctx, s.Db, entTenantContract.IdEQ(uuid.UUID(key)))
	case TenantDomainDomain:
		vs, err = rowsTenantDomain(ctx, s.Db, entTenantDomain.IdEQ(uuid.UUID(key)))
	case TreeLockDomain:
		vs, err = rowsTreeLock(ctx, s.Db, entTreeLock.IdEQ(uuid.UUID(key)))
	case WorkOrderDomain:
		vs, err = rowsWorkOrder(ctx, s.Db, entWorkOrder.IdEQ(uuid.UUID(key)))
	default:
		return nil, nil
	}
	if err != nil || len(vs) == 0 {
		return nil, err
	}

	return vs[0].Row, nil
}

// line is the line of the trail a write is about to be recorded as, decided
// before it is written so that the digest it keeps can be bound to it
// (payday#115): its key, as the servers mint one for the trail, and its
// moment by their clock, to the microsecond every database keeps.
func line(s bare.Server, action string) audit.Line {
	at := time.Now()
	if s.Now != nil {
		at = s.Now()
	}

	return audit.Line{
		Id:      pdid.New(AuditDomain),
		Created: at.UTC().Truncate(time.Microsecond),
		Action:  action,
	}
}

// digested is the digest the line `at` keeps of `row`, the row a write left
// of the thing `key` names, and the fields it covers: empty for a
// deployment that keeps none, and of the line alone for a write that left
// no row (payday#115) -- and what the write does to the row's seal, nil
// for a kind that declares no field `personal`.
//
// What the digest covers is the entity's fields less the ones it declared
// `personal`, which it leaves out however the row it is handed was read:
// the line that keeps it outlives the row, in the archive, and the person.
// A field declared `secret` is covered, since a keyed MAC of a verifier is
// neither a copy of it nor a way to test a guess at it without the key. The
// seal covers every field, the personal ones among them, and lives beside
// the row for as long as it does; a write that took the row removes it.
func digested(d *audit.Digest, key pdid.Id, row proto.Message, at audit.Line) ([]byte, []uint32, *rowSeal, error) {
	md, _, personal := described(key)
	switch {
	case d == nil || md == nil:
		return []byte{}, []uint32{}, nil, nil
	case row == nil:
		var gone *rowSeal
		if isSealed(key) {
			gone = &rowSeal{object: key, gone: true}
		}

		return d.Gone(key, at), []uint32{}, gone, nil
	}

	covered := audit.Covered(md, personal)
	if isSealed(key) {
		all := audit.Covered(md, nil)
		sum, sealSum, err := d.OfSealed(key, row, covered, all, at)
		if err != nil {
			return nil, nil, nil, err
		}

		return sum, covered, &rowSeal{object: key, sum: sealSum, fields: all}, nil
	}

	sum, err := d.Of(key, row, covered, at)
	if err != nil {
		return nil, nil, nil, err
	}

	return sum, covered, nil, nil
}

// keptTrail is the trail a transaction has recorded and not written yet.
//
// It is kept by the transaction ([dialect.Keep]) and written by its commit,
// or a few hundred rows at a time before that, or ahead of any statement
// about the trail the transaction sends. The commit is what writes it, so
// a transaction cannot be ended with any of it left out, and one rolled
// back takes it along unwritten.
type keptTrail struct {
	// db is the client of the first write the transaction recorded, which
	// is as good as any other's: every one of them is that transaction.
	db   *ent.Client
	rows []*ent.AuditCreate

	// writing is the rows being written, by a statement that is itself
	// about the trail: asked to write them first, it finds them on the way.
	writing bool
}

// keptTrailKey is what a transaction keeps its [keptTrail] under.
type keptTrailKey struct{}

// keptTrailRows is how many rows of the trail one statement writes.
const keptTrailRows = 500

// keptTrailAbout is whether a statement is about the trail: the table's
// name as a word of it. Every statement that is about it has what is kept
// written first, so that it finds every row the transaction recorded.
var keptTrailAbout = regexp.MustCompile(`\b` + regexp.QuoteMeta(entAudit.Table) + `\b`).MatchString

func keptTrailOf(k *dialect.Keep, db *ent.Client) *keptTrail {
	return k.Value(keptTrailKey{}, func() any {
		v := &keptTrail{db: db}
		k.BeforeCommit(v.write)
		k.BeforeStatement(keptTrailAbout, v.write)
		return v
	}).(*keptTrail)
}

func (v *keptTrail) add(ctx context.Context, q *ent.AuditCreate) error {
	v.rows = append(v.rows, q)
	if len(v.rows) < keptTrailRows {
		return nil
	}

	return v.write(ctx)
}

// write writes what is kept, a statement for each few hundred rows.
func (v *keptTrail) write(ctx context.Context) error {
	if v.writing {
		return nil
	}
	v.writing = true
	defer func() { v.writing = false }()

	for len(v.rows) > 0 {
		n := min(len(v.rows), keptTrailRows)
		if err := v.db.Audit.CreateBulk(v.rows[:n]...).Exec(ctx); err != nil {
			return fmt.Errorf("write the trail: %w", err)
		}
		v.rows = v.rows[n:]
	}

	return nil
}

// isSealed is whether rows of `key`'s kind are sealed: it is on the trail and
// declares a field `personal`, which the trail's digest leaves out and the
// row's seal covers (payday#115).
func isSealed(key pdid.Id) bool {
	switch key.Domain() {
	case EventDomain, HolderDomain, InvitationDomain, NotificationDomain, PartyDomain:
		return true
	}

	return false
}

// rowSeal is what a write does to the seal of one row: writes `sum`, over the
// fields `fields` lists, filed under `tenant` -- or, `gone`, removes it, for
// a write that took the row.
type rowSeal struct {
	object pdid.Id
	tenant uuid.UUID
	sum    []byte
	fields []uint32
	gone   bool
}

// in is `v` filed under `tenant`: where the write that made it filed its
// line. Nil for nil, which is a write that does nothing to a seal.
func (v *rowSeal) in(tenant uuid.UUID) *rowSeal {
	if v == nil {
		return nil
	}

	c := *v
	c.tenant = tenant
	return &c
}

// keepSeals does what `vs` say to the seals of their rows, in the transaction `db`
// runs in: kept for its commit when it keeps anything, as the trail is, and
// written now when it does not. A nil of `vs` is a write that does nothing
// to a seal.
func keepSeals(ctx context.Context, db *ent.Client, vs ...*rowSeal) error {
	vs = slices.DeleteFunc(vs, func(v *rowSeal) bool { return v == nil })
	if len(vs) == 0 {
		return nil
	}
	if k, ok := dialect.KeepOf(db.Driver()); ok {
		return keptSealsOf(k, db).add(ctx, vs)
	}

	return writeSeals(ctx, db, vs)
}

// keptSeals is the seals a transaction has written and not yet sent, kept by
// it ([dialect.Keep]) and written by its commit, a few hundred at a time
// before that, or ahead of any statement about the table -- as [keptTrail]
// is, and for the same reasons.
type keptSeals struct {
	db      *ent.Client
	vs      []*rowSeal
	writing bool
}

// keptSealsKey is what a transaction keeps its [keptSeals] under.
type keptSealsKey struct{}

// keptSealsAbout is whether a statement is about the seals: the table's
// name as a word of it.
var keptSealsAbout = regexp.MustCompile(`\b` + regexp.QuoteMeta(entRowSeal.Table) + `\b`).MatchString

func keptSealsOf(k *dialect.Keep, db *ent.Client) *keptSeals {
	return k.Value(keptSealsKey{}, func() any {
		v := &keptSeals{db: db}
		k.BeforeCommit(v.write)
		k.BeforeStatement(keptSealsAbout, v.write)
		return v
	}).(*keptSeals)
}

func (v *keptSeals) add(ctx context.Context, vs []*rowSeal) error {
	v.vs = append(v.vs, vs...)
	if len(v.vs) < keptSealsRows {
		return nil
	}

	return v.write(ctx)
}

func (v *keptSeals) write(ctx context.Context) error {
	if v.writing || len(v.vs) == 0 {
		return nil
	}
	v.writing = true
	defer func() { v.writing = false }()

	vs := v.vs
	v.vs = nil

	return writeSeals(ctx, v.db, vs)
}

// keptSealsRows is how many seals one statement writes.
const keptSealsRows = 500

// writeSeals sends what `vs` say: the last word about each row, the seals in
// an INSERT that writes over the seal there is, a few hundred a statement,
// and the seals of rows that went in one DELETE.
func writeSeals(ctx context.Context, db *ent.Client, vs []*rowSeal) error {
	last := map[pdid.Id]*rowSeal{}
	order := []pdid.Id{}
	for _, v := range vs {
		if _, ok := last[v.object]; !ok {
			order = append(order, v.object)
		}
		last[v.object] = v
	}

	put := []*rowSeal{}
	gone := []uuid.UUID{}
	for _, k := range order {
		if v := last[k]; v.gone {
			gone = append(gone, uuid.UUID(k))
		} else {
			put = append(put, v)
		}
	}

	drv := db.Driver()
	for page := range slices.Chunk(put, keptSealsRows) {
		q := sql.Dialect(drv.Dialect()).Insert(entRowSeal.Table).
			Columns(entRowSeal.FieldId, entRowSeal.FieldTenantId, entRowSeal.FieldSum, entRowSeal.FieldFields)
		for _, v := range page {
			fields, err := json.Marshal(v.fields)
			if err != nil {
				return err
			}
			q.Values(uuid.UUID(v.object), v.tenant, v.sum, json.RawMessage(fields))
		}
		q.OnConflict(sql.ConflictColumns(entRowSeal.FieldId), sql.ResolveWithNewValues())

		query, args := q.Query()
		var res sql1.Result
		if err := drv.Exec(ctx, query, args, &res); err != nil {
			return fmt.Errorf("write the seals: %w", err)
		}
	}
	for page := range slices.Chunk(gone, keptSealsRows) {
		if _, err := db.RowSeal.Delete().Where(entRowSeal.IdIn(page...)).Exec(ctx); err != nil {
			return fmt.Errorf("remove the seals: %w", err)
		}
	}

	return nil
}

// carrySeals binds the seals of the rows a pass carried a line forward for
// to the lines it wrote ([audit.Digest.CarrySeal]): what each said of its
// row, copied, and bound to the new line. A row with no seal has none to
// carry.
func carrySeals(ctx context.Context, db *ent.Client, d *audit.Digest, lines map[pdid.Id]audit.Line, tenants map[pdid.Id]uuid.UUID) error {
	if len(lines) == 0 {
		return nil
	}

	seals, err := sealsOf(ctx, db, slices.Collect(maps.Keys(lines)))
	if err != nil {
		return err
	}

	vs := make([]*rowSeal, 0, len(seals))
	for id, v := range seals {
		sum, err := d.CarrySeal(v.Sum, id, lines[id])
		if err != nil {
			return fmt.Errorf("carry the seal of %s forward: %w", id, err)
		}
		vs = append(vs, &rowSeal{object: id, tenant: tenants[id], sum: sum, fields: v.Fields})
	}

	return writeSeals(ctx, db, vs)
}

// sealsOf is the seal of each of `ids` that has one, as a check of the rows
// reads it.
func sealsOf(ctx context.Context, db *ent.Client, ids []pdid.Id) (map[pdid.Id]audit.Sealed, error) {
	out := map[pdid.Id]audit.Sealed{}
	if len(ids) == 0 {
		return out, nil
	}

	vs, err := db.RowSeal.Query().Where(entRowSeal.IdIn(uuids(ids)...)).All(ctx)
	if err != nil {
		return nil, err
	}
	for _, v := range vs {
		out[pdid.Id(v.Id)] = audit.Sealed{Sum: v.Sum, Fields: v.Fields}
	}

	return out, nil
}

// Digests checks every row of every kind on the trail -- every kind but the
// ones kept off it -- against the trail (payday#102, #108, #115): each
// digested again, as a Get reads it, and compared with the digest the newest
// line of the trail about it keeps -- in the database, or in the archive `p`
// names once it has left. A row somebody changed past the servers is one that
// differs, a row somebody added past them is one nothing on the trail is
// about, and a row somebody removed past them is a thing the trail says is a
// row and is not. The kinds it does not read are in what it answers, with
// why, so that a check that found nothing says what it did not look at.
//
// It changes nothing. It reads a page of a kind at a time, each page with the
// trail about it in one read-only transaction, so `db` is the database and
// not a transaction. With no archive, what is not in the database is not on
// the trail.
func Digests(ctx context.Context, db *ent.Client, d *audit.Digest, p trail.Policy) (audit.Rows, error) {
	var archived audit.Archived
	if p.Archive != nil {
		n, err := p.Newest(ctx, TrailStore(db))
		if err != nil {
			return audit.Rows{}, fmt.Errorf("the archive: %w", err)
		}
		archived = archivedDigests(n)
	}

	out := audit.Rows{Skipped: []audit.Skipped{
		{Kind: "handoff", Why: "a code a browser carries from the service's address to a workspace's domain, good once for a minute; the session it becomes is no act either, and who signed in where is the access record's"},
		{Kind: "search-stale", Why: "the search index's queue: that a document is to be made again, which the indexer takes within seconds"},
		{Kind: "session", Why: "a sign-in, whose idle clock moves on every request; who signed in, and from where, is the access record's (rove#136)"},
		{Kind: "sign-in-failure", Why: "a count of the sign-ins an address got wrong, kept for hours to slow the next; nobody's act"},
		{Kind: "tree-lock", Why: "the lock every change of the placement tree takes, and its version: bookkeeping, not a fact"},
	}}
	if err := audit.CheckKind(ctx, d, checkedAccessReview(db), archived, &out); err != nil {
		return out, fmt.Errorf("access-review: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAliasHold(db), archived, &out); err != nil {
		return out, fmt.Errorf("alias-hold: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAllocation(db), archived, &out); err != nil {
		return out, fmt.Errorf("allocation: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAsset(db), archived, &out); err != nil {
		return out, fmt.Errorf("asset: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAssetType(db), archived, &out); err != nil {
		return out, fmt.Errorf("asset-type: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedAttachment(db), archived, &out); err != nil {
		return out, fmt.Errorf("attachment: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedBookable(db), archived, &out); err != nil {
		return out, fmt.Errorf("bookable: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedCliLogin(db), archived, &out); err != nil {
		return out, fmt.Errorf("cli-login: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedCountFinding(db), archived, &out); err != nil {
		return out, fmt.Errorf("count-finding: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedCustody(db), archived, &out); err != nil {
		return out, fmt.Errorf("custody: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedCustodyLine(db), archived, &out); err != nil {
		return out, fmt.Errorf("custody-line: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedEvent(db), archived, &out); err != nil {
		return out, fmt.Errorf("event: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedFact(db), archived, &out); err != nil {
		return out, fmt.Errorf("fact: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedHolder(db), archived, &out); err != nil {
		return out, fmt.Errorf("holder: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedInventoryCount(db), archived, &out); err != nil {
		return out, fmt.Errorf("inventory-count: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedInvitation(db), archived, &out); err != nil {
		return out, fmt.Errorf("invitation: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedItemModel(db), archived, &out); err != nil {
		return out, fmt.Errorf("item-model: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedLabel(db), archived, &out); err != nil {
		return out, fmt.Errorf("label: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedLegalHold(db), archived, &out); err != nil {
		return out, fmt.Errorf("legal-hold: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedLink(db), archived, &out); err != nil {
		return out, fmt.Errorf("link: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedNotification(db), archived, &out); err != nil {
		return out, fmt.Errorf("notification: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedParty(db), archived, &out); err != nil {
		return out, fmt.Errorf("party: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedPlacement(db), archived, &out); err != nil {
		return out, fmt.Errorf("placement: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedPurchase(db), archived, &out); err != nil {
		return out, fmt.Errorf("purchase: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedPurchaseLine(db), archived, &out); err != nil {
		return out, fmt.Errorf("purchase-line: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedReservation(db), archived, &out); err != nil {
		return out, fmt.Errorf("reservation: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedReservationItem(db), archived, &out); err != nil {
		return out, fmt.Errorf("reservation-item: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedStewardship(db), archived, &out); err != nil {
		return out, fmt.Errorf("stewardship: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedStock(db), archived, &out); err != nil {
		return out, fmt.Errorf("stock: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedStockMovement(db), archived, &out); err != nil {
		return out, fmt.Errorf("stock-movement: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedTenant(db), archived, &out); err != nil {
		return out, fmt.Errorf("tenant: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedTenantContract(db), archived, &out); err != nil {
		return out, fmt.Errorf("tenant-contract: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedTenantDomain(db), archived, &out); err != nil {
		return out, fmt.Errorf("tenant-domain: %w", err)
	}
	if err := audit.CheckKind(ctx, d, checkedWorkOrder(db), archived, &out); err != nil {
		return out, fmt.Errorf("work-order: %w", err)
	}

	return out, nil
}

// checkedAccessReview is what a check of the rows reads of the access-review kind.
func checkedAccessReview(db *ent.Client) audit.Kind {
	read := func(ctx context.Context, ps ...predicate.AccessReview) (audit.Page, error) {
		var out audit.Page
		err := snapshot(ctx, db, func(ctx context.Context, db *ent.Client) error {
			rows, err := rowsAccessReview(ctx, db, ps...)
			if err != nil {
				return err
			}

			recorded, err := newestDigests(ctx, db, objects(rows))
			out = audit.Page{Rows: rows, Recorded: recorded}
			return err
		})

		return out, err
	}

	return audit.Kind{
		Domain: AccessReviewDomain,
		After: func(ctx context.Context, after pdid.Id) (audit.Page, error) {
			return read(ctx, entAccessReview.IdGT(uuid.UUID(after)))
		},
		Of: func(ctx context.Context, ids []pdid.Id) (audit.Page, error) {
			return read(ctx, entAccessReview.IdIn(uuids(ids)...))
		},
		Trail: func(ctx context.Context, yield func([]pdid.Id) error) error {
			return trailObjects(ctx, db, AccessReviewDomain, yield)
		},
		Gone: func(ctx context.Context, ids []pdid.Id) (map[pdid.Id]*audit.Recorded, error) {
			var out map[pdid.Id]*audit.Recorded
			err := snapshot(ctx, db, func(ctx context.Context, db *ent.Client) error {
				rows, err := rowsAccessReview(ctx, db, entAccessReview.IdIn(uuids(ids)...))
				if err != nil {
					return err
				}

				out, err = goneOf(ctx, db, ids, rows)
				return err
			})

			return out, err
		},
	}
}

