// rowsAccessReview is the rows `ps` says of the access-review kind -- every row there is,
// live or erased softly -- at most a page of them in identifier order, each as
// a Get reads it.
func rowsAccessReview(ctx context.Context, db *ent.Client, ps ...predicate.AccessReview) ([]audit.Live, error) {
	q := db.AccessReview.Query().Where(ps...)
	bare.AccessReviewSelectInit(q, nil)

	vs, err := q.Order(entAccessReview.ById()).Limit(audit.RowsPage).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make([]audit.Live, len(vs))
	for i, v := range vs {
		out[i] = audit.Live{Object: pdid.Id(v.Id), Row: v.Proto()}
	}

	return out, nil
}

